import { Router, Request, Response } from 'express';
import { TelemetryReasoningPoller } from '../../domain/reasoning/TelemetryReasoningPoller';

const router = Router();
const poller = TelemetryReasoningPoller.getInstance();

/**
 * GET /api/v1/reasoning/latest
 * Returns the most recent Reasoning Report generated by Gemini from database telemetry.
 */
router.get('/latest', async (req: Request, res: Response) => {
  try {
    const userId = (req.query.userId as string) || 'tunemind-dev';
    let report = poller.getLatestReport(userId);

    // If no report exists yet, trigger an immediate poll to generate one
    if (!report) {
      report = await poller.pollNow(userId);
    }

    res.json({
      status: 'ok',
      report
    });
  } catch (error) {
    console.error('[reasoning.ts] Error retrieving latest report:', error);
    res.status(500).json({
      status: 'error',
      message: (error as Error).message
    });
  }
});

/**
 * GET /api/v1/reasoning/reports
 * Returns the chronological history of generated Reasoning Reports.
 */
router.get('/reports', (req: Request, res: Response) => {
  try {
    const userId = req.query.userId as string | undefined;
    const reports = poller.getReportHistory(userId);
    res.json({
      status: 'ok',
      reports
    });
  } catch (error) {
    console.error('[reasoning.ts] Error retrieving reports history:', error);
    res.status(500).json({
      status: 'error',
      message: (error as Error).message
    });
  }
});

/**
 * POST /api/v1/reasoning/trigger
 * Manually prompts the poller to fetch current telemetry events from the database
 * and run a Gemini reasoning synthesis immediately.
 */
router.post('/trigger', async (req: Request, res: Response) => {
  try {
    const userId = (req.body?.userId as string) || (req.query.userId as string) || 'tunemind-dev';
    const report = await poller.pollNow(userId);

    res.json({
      status: 'ok',
      message: 'Reasoning analysis completed successfully',
      report
    });
  } catch (error) {
    console.error('[reasoning.ts] Error triggering reasoning analysis:', error);
    res.status(500).json({
      status: 'error',
      message: (error as Error).message
    });
  }
});

/**
 * GET /api/v1/reasoning/status
 * Returns the operational health and configuration state of the telemetry reasoning poller.
 */
router.get('/status', async (_req: Request, res: Response) => {
  try {
    const status = await poller.getStatus();
    res.json({
      status: 'ok',
      ...status
    });
  } catch (error) {
    console.error('[reasoning.ts] Error retrieving poller status:', error);
    res.status(500).json({
      status: 'error',
      message: (error as Error).message
    });
  }
});

export default router;
